-- Seed data: plans, learning modes, lesson categories, starter lessons.
-- Idempotent (ON CONFLICT DO NOTHING). Plan limits are configurable rows, not code.

insert into public.plans (code, name, daily_voice_seconds, monthly_voice_seconds, daily_sessions, max_session_seconds) values
  ('free',    'Free',    600,  9000,  5, 600),
  ('premium', 'Premium', 5400, 108000, 30, 1500)
on conflict (code) do nothing;

insert into public.learning_modes (code, name, description, icon, instructions, topics, sort_order) values
  ('free_conversation', 'Free Conversation', 'Talk about anything you like. Your teacher listens and gently corrects.', 'message-circle',
   'Hold a relaxed, natural conversation on whatever the student wants. Follow their interests and keep asking friendly follow-up questions.',
   array['Anything you like','Hobbies','News and ideas','Your dreams'], 1),
  ('daily_english', 'Daily English', 'Practise everyday situations: greetings, family, school, work, shopping and more.', 'sun',
   'Guide the student through everyday topics. Teach useful, natural phrases people really say.',
   array['Greetings','Family','School','Work','Shopping','Food','Travel','Transportation','Friends','Daily routine'], 2),
  ('grammar', 'Grammar Practice', 'Short spoken drills on tenses, articles, prepositions and common mistakes.', 'spell-check',
   'Teach one grammar point at a time with a one-sentence rule, two examples, then make the student produce their own sentences aloud. Correct every error on the target point.',
   array['Present tense','Past tense','Future','Articles','Prepositions','Pronouns','Adjectives','Adverbs','Modal verbs','Conditionals','Sentence structure','Common mistakes'], 3),
  ('vocabulary', 'Vocabulary', 'Learn useful words for your level and use them in your own sentences.', 'book-a',
   'Introduce 3 to 5 useful words at a time suited to the level. Give a simple meaning and an example, then ask the student to use each word in a sentence.',
   array['Everyday words','Work and study','Feelings','Food and cooking','Travel words','Phrasal verbs'], 4),
  ('pronunciation', 'Pronunciation', 'Practise saying words and sentences clearly. Feedback is conversational, not a score.', 'audio-lines',
   'Help the student practise difficult sounds and word stress by modelling words and asking them to repeat. You are NOT measuring pronunciation with instruments, so give honest, general listening-based feedback only and never give numeric pronunciation scores.',
   array['Vowel sounds','th sounds','Word stress','Sentence rhythm','Minimal pairs'], 5),
  ('interview', 'Interview Practice', 'Rehearse job interviews with a friendly but realistic interviewer.', 'briefcase',
   'Act as a professional interviewer for the role the student names (ask if unknown). Ask one interview question at a time, then give brief feedback on both the English and the content of the answer.',
   array['Tell me about yourself','Strengths and weaknesses','Why this job','Teamwork stories','Questions for the interviewer'], 6),
  ('business', 'Business English', 'Meetings, presentations, customer calls, negotiation and workplace chat.', 'building-2',
   'Practise professional English: meetings, presentations, customer communication, negotiation and workplace conversation. Teach polite, professional phrases.',
   array['Meetings','Presentations','Customer communication','Negotiation','Workplace conversations'], 7),
  ('travel', 'Travel English', 'Airport, hotel, restaurant, taxi, immigration and asking for directions.', 'plane',
   'Role-play travel situations realistically, playing the other person (officer, receptionist, waiter, driver). Stay in character but pause to teach useful phrases.',
   array['Airport','Hotel','Restaurant','Taxi','Immigration','Asking for directions'], 8),
  ('storytelling', 'Storytelling', 'Tell stories about your life. Your teacher helps you tell them better.', 'book-open',
   'Invite the student to tell a story. Let them finish, ask follow-up questions, then give a few important corrections and help them retell one part better.',
   array['A memorable day','My hometown','A funny moment','My childhood','A person I admire'], 9),
  ('role_play', 'Role Play', 'Realistic scenarios where you practise what you would really say.', 'drama',
   'Set up a realistic scenario in one sentence, play your role naturally, and stay in character. Step out briefly to teach phrases when the student struggles.',
   array['At the doctor','Making a complaint','Phone call','Making plans with a friend','Renting a flat'], 10)
on conflict (code) do nothing;

insert into public.lesson_categories (slug, name, description, icon, sort_order) values
  ('grammar',    'Grammar',           'Core grammar rules with spoken practice.', 'spell-check', 1),
  ('speaking',   'Speaking',          'Build fluency and confidence.', 'mic', 2),
  ('vocabulary', 'Vocabulary',        'Words and phrases you will use every day.', 'book-a', 3),
  ('listening',  'Listening',         'Train your ear for natural English.', 'headphones', 4),
  ('pronunciation', 'Pronunciation',  'Clearer sounds, stress and rhythm.', 'audio-lines', 5),
  ('everyday',   'Everyday English',  'Real situations from daily life.', 'sun', 6),
  ('business',   'Business English',  'Professional communication at work.', 'building-2', 7),
  ('interview',  'Interview English', 'Prepare for job interviews.', 'briefcase', 8)
on conflict (slug) do nothing;

-- ───────────── lessons ─────────────
insert into public.lessons (category_id, slug, title, description, level, objective, content, examples, exercises, suggested_mode, estimated_minutes, sort_order)
select c.id, v.slug, v.title, v.description, v.level, v.objective, v.content, v.examples::jsonb, v.exercises::jsonb, v.suggested_mode, v.minutes, v.sort_order
from (values
  ('grammar','present-simple-be','To be: I am, you are, he is','Introduce yourself and describe people with the verb "to be".','beginner',
   'Use am, is and are correctly in simple sentences.',
   E'We use "to be" to say who or what someone is.\n\n• I am\n• You are\n• He / She / It is\n• We / They are\n\nShort forms are common in speech: I''m, you''re, he''s, she''s, we''re, they''re.\n\nFor questions, swap the order: "Are you a student?" For negatives add not: "She is not (isn''t) tired."',
   '[{"text":"I am a student.","note":"Use am with I."},{"text":"She is my sister.","note":"Use is with he, she and it."},{"text":"They are from Nigeria.","note":"Use are with we, you and they."}]',
   '[{"type":"fill","prompt":"My brother ___ a teacher.","answer":"is"},{"type":"fill","prompt":"We ___ happy today.","answer":"are"},{"type":"fill","prompt":"I ___ from Abuja.","answer":"am"}]',
   'grammar',10,1),
  ('grammar','past-simple-regular-irregular','Talking about yesterday: past simple','Use regular and common irregular past tense verbs.','elementary',
   'Make correct past simple sentences about finished actions.',
   E'Use the past simple for actions that finished in the past.\n\nRegular verbs add -ed: walk → walked, play → played.\nIrregular verbs change: go → went, eat → ate, see → saw, have → had.\n\nFor questions and negatives use did + the base verb: "Did you go?" "I did not (didn''t) go." Do not put -ed after did.',
   '[{"text":"I went to the market yesterday.","note":"went is the past of go."},{"text":"She did not watch TV last night.","note":"After did not, use the base verb."},{"text":"Did you eat breakfast?","note":"Did + base verb for questions."}]',
   '[{"type":"fill","prompt":"Yesterday I ___ (go) to school.","answer":"went"},{"type":"fill","prompt":"She ___ (not / call) me.","answer":"did not call"},{"type":"fill","prompt":"___ you see the match? (question)","answer":"Did"}]',
   'grammar',12,2),
  ('grammar','present-perfect-vs-past','Present perfect or past simple?','Choose the right tense for experiences and finished times.','intermediate',
   'Decide between "I have been" and "I went" depending on whether the time is finished.',
   E'Use the past simple with a finished time: "I went to Lagos in 2022." "I saw him yesterday."\n\nUse the present perfect (have/has + past participle) for experiences or results connected to now, with no finished time: "I have been to Lagos." "She has lost her keys."\n\nWords like yesterday, last week and in 2022 need the past simple. Words like ever, never, already, yet and just usually go with the present perfect. A common mistake is "I have went": the participle of go is gone/been, not went.',
   '[{"text":"I have never visited London.","note":"Experience, no finished time."},{"text":"I visited London last summer.","note":"Finished time: past simple."},{"text":"Have you finished your homework yet?","note":"yet goes with present perfect."}]',
   '[{"type":"choice","prompt":"I ___ my keys yesterday. (lost / have lost)","answer":"lost"},{"type":"choice","prompt":"She ___ never ___ sushi. (has / ate / eaten)","answer":"has eaten"}]',
   'grammar',15,3),
  ('grammar','conditionals-real-unreal','Conditionals: real and unreal','First and second conditionals for plans and imagined situations.','upper_intermediate',
   'Form and use first and second conditionals fluently when speaking.',
   E'First conditional (real possibility): if + present simple, will + base verb. "If it rains, we will stay home."\n\nSecond conditional (unreal or unlikely): if + past simple, would + base verb. "If I had more time, I would learn French."\n\nIn the second conditional, "were" is commonly used for all persons in careful speech: "If I were you, I would apologise." Avoid "will" inside the if-clause.',
   '[{"text":"If you study, you will pass.","note":"Real possibility."},{"text":"If I were rich, I would travel the world.","note":"Imaginary situation."}]',
   '[{"type":"fill","prompt":"If I ___ (have) a car, I would drive to work.","answer":"had"},{"type":"fill","prompt":"If she calls, I ___ (tell) her.","answer":"will tell"}]',
   'grammar',15,4),
  ('everyday','greetings-introductions','Greetings and introductions','Say hello, introduce yourself and ask simple questions.','beginner',
   'Greet someone, give your name and ask how they are.',
   E'Common greetings: Hello, Hi, Good morning, Good afternoon, Good evening.\n\nIntroduce yourself: "My name is Amina." "I''m from Kano." "Nice to meet you."\n\nAsk: "How are you?" "What do you do?" "Where are you from?"\n\nTypical replies: "I''m fine, thank you. And you?"',
   '[{"text":"Hello! My name is Musa. Nice to meet you.","note":"A complete introduction."},{"text":"How are you today?","note":"A friendly question."}]',
   '[{"type":"speak","prompt":"Introduce yourself in three sentences: your name, where you are from and what you do.","answer":""}]',
   'daily_english',8,1),
  ('everyday','shopping-at-the-market','Shopping at the market','Ask about prices, quantities and bargain politely.','elementary',
   'Ask for items, prices and quantities in a shop or market.',
   E'Useful questions: "How much is this?" "How much are these?" "Do you have a smaller one?" "Can I have two kilos, please?"\n\nBargaining politely: "That''s a bit expensive. Can you give me a better price?"\n\nPaying: "I''ll take it." "Here you are." "Do you accept cards?"',
   '[{"text":"How much are these tomatoes?","note":"Use are with plural items."},{"text":"Can I have half a kilo, please?","note":"Polite request."}]',
   '[{"type":"speak","prompt":"Role-play buying three things at the market and asking for a better price.","answer":""}]',
   'role_play',10,2),
  ('speaking','describing-your-day','Describing your daily routine','Talk about your day using time expressions and sequence words.','elementary',
   'Speak for one minute about a normal day using first, then, after that and finally.',
   E'Use present simple for routines: "I wake up at six." Use sequence words: first, then, after that, later, finally.\n\nAdd frequency words: always, usually, often, sometimes, never. They go before the main verb: "I usually eat at home."',
   '[{"text":"First I wake up at six, then I pray and have breakfast.","note":"Sequence words connect ideas."},{"text":"I never drink coffee in the evening.","note":"Frequency word before the verb."}]',
   '[{"type":"speak","prompt":"Describe your morning routine for one minute.","answer":""}]',
   'free_conversation',10,1),
  ('speaking','telling-a-story','Telling a story with confidence','Use past tenses and linking words to tell a clear story.','intermediate',
   'Tell a short story with a beginning, middle and end using past tenses.',
   E'A good story has a setting, a problem and an ending. Start with: "Last year, I..." or "One day..."\n\nUse past simple for main events and past continuous for background: "I was walking home when it started to rain."\n\nLink ideas: so, because, but, then, suddenly, in the end.',
   '[{"text":"I was walking home when I met an old friend.","note":"Past continuous + past simple."},{"text":"In the end, we laughed about it.","note":"A clear ending."}]',
   '[{"type":"speak","prompt":"Tell a two-minute story about a surprising day in your life.","answer":""}]',
   'storytelling',12,2),
  ('speaking','giving-opinions','Giving and defending opinions','Express agreement, disagreement and reasons politely.','upper_intermediate',
   'Give an opinion with a reason and respond politely to a different view.',
   E'Giving opinions: "In my opinion...", "I believe...", "From my point of view...".\n\nGiving reasons: "because", "since", "for example".\n\nDisagreeing politely: "I see your point, but...", "I''m not sure I agree because..."\n\nBalance your view: "On the one hand... on the other hand...".',
   '[{"text":"In my opinion, learning English is easier when you speak every day.","note":"Opinion + reason."},{"text":"I see your point, but I think the cost is too high.","note":"Polite disagreement."}]',
   '[{"type":"speak","prompt":"Should students use phones in class? Give your opinion with two reasons.","answer":""}]',
   'free_conversation',12,3),
  ('vocabulary','family-and-friends-words','Family and friends vocabulary','Words for relatives and relationships.','beginner',
   'Name family members and describe relationships.',
   E'Family: mother, father, parents, brother, sister, grandmother, grandfather, uncle, aunt, cousin.\n\nFriends: friend, best friend, neighbour, classmate, colleague.\n\nUseful sentence frames: "This is my ___." "She is my ___''s sister." "I have two brothers and one sister."',
   '[{"text":"This is my uncle. He is a doctor.","note":"Introduce a relative."},{"text":"I have two sisters.","note":"Use have for family size."}]',
   '[{"type":"speak","prompt":"Describe your family in five sentences.","answer":""}]',
   'vocabulary',8,1),
  ('vocabulary','phrasal-verbs-everyday','Everyday phrasal verbs','Ten phrasal verbs that native speakers use all the time.','intermediate',
   'Understand and use common phrasal verbs in sentences.',
   E'Phrasal verbs combine a verb and a small word, and the meaning often changes.\n\n• wake up – stop sleeping\n• give up – stop trying\n• look for – search\n• find out – discover\n• turn on / turn off – start / stop a device\n• run out of – have none left\n• get along with – have a good relationship with\n• put off – delay\n• work out – exercise, or solve\n• come up with – think of an idea',
   '[{"text":"We ran out of milk, so I went to the shop.","note":"run out of = have none left."},{"text":"Don''t give up. You are improving!","note":"give up = stop trying."}]',
   '[{"type":"fill","prompt":"I''m ___ my keys. I can''t find them. (looking for / looking at)","answer":"looking for"}]',
   'vocabulary',12,2),
  ('vocabulary','advanced-collocations','Natural collocations','Word partners that make your English sound natural.','advanced',
   'Replace weak word choices with natural collocations.',
   E'Collocations are words that naturally go together. We say "make a decision", not "do a decision"; "heavy rain", not "strong rain"; "do homework", not "make homework".\n\nLearn words in chunks: take a risk, reach a conclusion, meet a deadline, raise awareness, pay attention, break the news.',
   '[{"text":"We need to make a decision by Friday.","note":"make a decision."},{"text":"She finally reached a conclusion.","note":"reach a conclusion."}]',
   '[{"type":"choice","prompt":"We must ___ the deadline. (meet / do)","answer":"meet"}]',
   'vocabulary',12,3),
  ('pronunciation','th-sounds','The "th" sounds','Practise the two th sounds in think and this.','elementary',
   'Produce the th sounds without replacing them with t, d, s or z.',
   E'English has two th sounds. Put the tip of your tongue lightly between your teeth.\n\nVoiceless th (no voice): think, three, thanks, month.\nVoiced th (vibrate your throat): this, that, mother, weather.\n\nPractise slowly: "Thank you very much." "This is my brother." Your teacher can listen and give general feedback, but remember this is practice, not an accurate pronunciation score.',
   '[{"text":"I think this is the third one.","note":"Both th sounds."}]',
   '[{"type":"speak","prompt":"Say: Three thin thieves thought they were thankful.","answer":""}]',
   'pronunciation',8,1),
  ('business','meeting-phrases','Phrases for meetings','Open, lead and close a meeting politely.','intermediate',
   'Use clear professional phrases to agree, disagree and summarise.',
   E'Starting: "Let''s get started." "Thanks for joining."\nSharing views: "I''d like to suggest...", "My concern is..."\nAgreeing: "That makes sense." Disagreeing: "I see it differently."\nClarifying: "Could you clarify what you mean by...?"\nClosing: "To summarise...", "Let''s follow up by Friday."',
   '[{"text":"Could you clarify what you mean by priority?","note":"Polite clarification."},{"text":"To summarise, we agreed to launch in May.","note":"Closing a meeting."}]',
   '[{"type":"speak","prompt":"Role-play opening a team meeting and proposing a new idea.","answer":""}]',
   'business',12,1),
  ('business','presentation-openings','Opening a presentation','Start a presentation with confidence.','upper_intermediate',
   'Open a presentation with a hook, a purpose and a roadmap.',
   E'Greet: "Good morning everyone, thank you for coming."\nState your purpose: "Today I''m going to talk about..."\nGive a roadmap: "I''ll cover three points: first, second, finally."\nInvite questions: "Please feel free to interrupt."',
   '[{"text":"Today I''m going to show you how we can cut costs by ten percent.","note":"Clear purpose."}]',
   '[{"type":"speak","prompt":"Deliver a 60-second opening for a presentation about a topic you know.","answer":""}]',
   'business',12,2),
  ('interview','tell-me-about-yourself','Tell me about yourself','Answer the most common interview opener clearly.','intermediate',
   'Give a 60-second professional introduction: present, past, future.',
   E'A simple structure: Present (what you do now), Past (relevant experience), Future (why you want this role).\n\n"I''m currently a ___ at ___. Before that, I ___. I''m excited about this role because ___."\n\nKeep it to about one minute. Use past simple for finished jobs and present simple for your current role.',
   '[{"text":"I''m currently a sales assistant. Before that, I studied business at university.","note":"Present then past."}]',
   '[{"type":"speak","prompt":"Answer: Tell me about yourself.","answer":""}]',
   'interview',12,1),
  ('interview','strengths-weaknesses','Strengths and weaknesses','Talk honestly about your strengths and areas to grow.','upper_intermediate',
   'Describe a strength with evidence and a weakness with a plan to improve.',
   E'Strength + evidence: "I''m very organised. For example, I managed three projects at once."\nWeakness + improvement: "I used to find public speaking difficult, so I joined a speaking club."\n\nUseful verbs: manage, improve, deliver, learn, lead, solve.',
   '[{"text":"I used to avoid presentations, but now I volunteer for them.","note":"A weakness with growth."}]',
   '[{"type":"speak","prompt":"Describe one strength and one weakness with examples.","answer":""}]',
   'interview',12,2),
  ('listening','understanding-fast-speech','Understanding fast, natural speech','Learn how native speakers link and shorten words.','upper_intermediate',
   'Recognise common reductions like gonna, wanna and "whaddya".',
   E'Native speakers link words and shorten them: going to → gonna, want to → wanna, did you → didja, a lot of → a lotta.\n\nPractise by asking your teacher to speak naturally, then to repeat more slowly. Ask: "Could you say that again more slowly?"',
   '[{"text":"I''m gonna call you later.","note":"gonna = going to."}]',
   '[{"type":"speak","prompt":"Ask your teacher to say three sentences naturally, then slowly, and repeat them.","answer":""}]',
   'free_conversation',10,1),
  ('speaking','advanced-discussion','Discussing complex topics','Handle abstract topics, hypotheticals and nuance.','advanced',
   'Sustain a five-minute discussion on an abstract topic with nuance.',
   E'Use hedging: "It could be argued that...", "To some extent...". Use concession: "Admittedly... however...". Use hypotheticals: "Were that to happen...".\n\nPractise topics such as technology and society, education systems and the future of work.',
   '[{"text":"It could be argued that technology has made us more connected but less present.","note":"Hedging language."}]',
   '[{"type":"speak","prompt":"Discuss whether remote work is better than office work, with nuance.","answer":""}]',
   'free_conversation',15,4)
) as v(cat, slug, title, description, level, objective, content, examples, exercises, suggested_mode, minutes, sort_order)
join public.lesson_categories c on c.slug = v.cat
on conflict (slug) do nothing;
